def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str):
        if token and token.isascii() and token.isdigit():
            return int(token)
        return None

    for idx, op in enumerate(ops):
        parts = op.split(" ")
        if any(not part for part in parts):
            rejected.append(idx)
            continue

        verb = parts[0]

        if verb == "open" and len(parts) == 3:
            acct, amount = parts[1], parse_amount(parts[2])
            if amount is not None and acct not in balances:
                balances[acct] = amount
                history.append(("open", acct))
                continue

        elif verb == "deposit" and len(parts) == 3:
            acct, amount = parts[1], parse_amount(parts[2])
            if amount is not None and amount > 0 and acct in balances:
                balances[acct] += amount
                history.append(("deposit", acct, amount))
                continue

        elif verb == "withdraw" and len(parts) == 3:
            acct, amount = parts[1], parse_amount(parts[2])
            if (
                amount is not None
                and amount > 0
                and acct in balances
                and acct not in frozen
                and balances[acct] >= amount
            ):
                balances[acct] -= amount
                history.append(("withdraw", acct, amount))
                continue

        elif verb == "transfer" and len(parts) == 4:
            src, dst, amount = parts[1], parts[2], parse_amount(parts[3])
            if (
                amount is not None
                and amount > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amount
            ):
                balances[src] -= amount
                balances[dst] += amount
                history.append(("transfer", src, dst, amount))
                continue

        elif verb == "freeze" and len(parts) == 2:
            acct = parts[1]
            if acct in balances and acct not in frozen:
                frozen.add(acct)
                history.append(("freeze", acct))
                continue

        elif verb == "unfreeze" and len(parts) == 2:
            acct = parts[1]
            if acct in balances and acct in frozen:
                frozen.remove(acct)
                history.append(("unfreeze", acct))
                continue

        elif verb == "undo" and len(parts) == 1:
            if history:
                action = history.pop()
                kind = action[0]
                if kind == "open":
                    acct = action[1]
                    del balances[acct]
                    frozen.discard(acct)
                elif kind == "deposit":
                    _, acct, amount = action
                    balances[acct] -= amount
                elif kind == "withdraw":
                    _, acct, amount = action
                    balances[acct] += amount
                elif kind == "transfer":
                    _, src, dst, amount = action
                    balances[src] += amount
                    balances[dst] -= amount
                elif kind == "freeze":
                    frozen.remove(action[1])
                elif kind == "unfreeze":
                    frozen.add(action[1])
                continue

        rejected.append(idx)

    return balances, rejected
